             "Skrip Python:\nimport numpy as np, scipy.stats as stats\ndef automated_paired_experiment(before, after, alpha=0.05):\n    diff = np.array(before) - np.array(after)\n    # 1. Uji Normalitas Selisih\n    _, p_norm = stats.shapiro(diff)\n    # 2. Pemilihan Uji Otomatis\n    if p_norm > alpha:\n        t_stat, p_val = stats.ttest_rel(before, after)\n        test_name = 'Paired t-Test (Parametrik)'\n    else:\n        t_stat, p_val = stats.wilcoxon(before, after)\n        test_name = 'Wilcoxon Signed-Rank (Non-Parametrik)'\n    # 3. Cohen's d Effect Size\n    d = np.mean(diff) / np.std(diff, ddof=1)\n    print(f'=== Hasil Eksperimen: {test_name} ===')\n    print(f'Statistik: {t_stat:.4f} | p-value: {p_val:.4e} | Cohen d: {d:.3f}')\n    return {'test': test_name, 'p_val': p_val, 'cohen_d': d}",
