             "Skrip Python:\nimport pandas as pd, scipy.stats as stats, statsmodels.api as sm\nfrom statsmodels.formula.api import ols\nimport matplotlib.pyplot as plt, seaborn as sns\n# 1. Independent t-Test\nscore_old = df_sim[df_sim['version']=='Old']['sus_score']\nscore_new = df_sim[df_sim['version']=='New']['sus_score']\nt_stat, p_val = stats.ttest_ind(score_old, score_new)\nprint(f'Independent t-Test: t = {t_stat:.4f}, p-value = {p_val:.4e}')\n# 2. Two-Way ANOVA Faktorial\nmodel = ols('sus_score ~ C(version) * C(user_group)', data=df_sim).fit()\nanova_res = sm.stats.anova_lm(model, typ=2)\nprint('\\n=== Tabel Two-Way ANOVA ===')\ndisplay(anova_res)\n# 3. Visualisasi Boxplot\nplt.figure(figsize=(9, 5))\nsns.boxplot(data=df_sim, x='user_group', y='sus_score', hue='version', palette=['#718096', '#3182CE'])\nplt.axhline(68.0, color='red', linestyle='--', label='Benchmark Industri (68.0)')\nplt.title('Perbandingan Skor Usabilitas SUS: Versi Lama vs Baru per Kelompok Pengguna', fontweight='bold')\nplt.ylabel('Skor SUS'); plt.legend(); plt.show()",
