             "Skrip Python:\nimport pandas as pd, numpy as np, scipy.stats as stats\nimport matplotlib.pyplot as plt, seaborn as sns\n# 1. Perhitungan N-Gain Hake (Max Score = 100)\ndf_game['n_gain'] = (df_game['posttest'] - df_game['pretest']) / (100.0 - df_game['pretest'])\nprint(f'Rata-rata N-Gain: {df_game[\"n_gain\"].mean():.4f} (Kategori: {\"Tinggi\" if df_game[\"n_gain\"].mean()>=0.7 else \"Sedang\"})')\n# 2. Paired t-Test\nt_stat, p_val = stats.ttest_rel(df_game['posttest'], df_game['pretest'])\nprint(f'Paired t-Test: t = {t_stat:.4f}, p-value = {p_val:.4e}')\n# 3. Korelasi MDA Rating vs N-Gain\nr_val, p_corr = stats.pearsonr(df_game['mda_satisfaction'], df_game['n_gain'])\nprint(f'Korelasi Kepuasan MDA vs N-Gain: r = {r_val:.4f} (p = {p_corr:.4e})')\n# 4. Visualisasi Distribusi Pre vs Post\nplt.figure(figsize=(8, 5))\nsns.kdeplot(df_game['pretest'], label='Pre-Test (Sebelum Bermain)', color='#E53E3E', fill=True)\nsns.kdeplot(df_game['posttest'], label='Post-Test (Sesudah Bermain)', color='#3182CE', fill=True)\nplt.title('Distribusi Peningkatan Pemahaman Siswa: Pre-Test vs Post-Test', fontweight='bold')\nplt.xlabel('Skor Tes (0 - 100)'); plt.legend(); plt.show()",
